import {locationFor} from '/shared/tencent-location.js';
import {$,esc,date,api,icon,toast,modal,closeModal,formSubmit,field,errorHTML,photoPicker,passwordDialog} from '/shared/ui.js';
import {campusMap,inCampus} from '/shared/map.js';
import {navigationPanel,bindNavigation,stopNavigation} from '/shared/navigation.js';
import {authURL} from '/shared/auth-routing.js';
import {journeyHTML,mountJourney} from './journey.js';
import {avatarHTML,profileDialog} from '/shared/profile.js';
import {searchHTML,bindSearch,cleanQuery} from './search.js';
import {localDraft,bindDraftForm,draftNotice,pruneDrafts} from '/shared/drafts.js';
import {mapExplorerHTML,mapPointHTML,chooseMapPoint} from './map-explorer.js';
function accountDraft(context){return localDraft(state.account.id,context);}
function draftPhoto(onSaved,context,{keepDraft=false,confirmedMediaId=null}={}){
 const draft=accountDraft(context);draft.reopen();
 return photoPicker(onSaved,{draft,notice:draftNotice(draft,{noun:'照片'}),keepDraft,confirmedMediaId});
}
const state={catalog:null,account:null,page:'discover',theme:'全部',query:'',map:null,active:null,sessions:[],preferences:{budget:20,people:1,intensity:'轻松',theme:'全部',mode:'fixed'}};
const nav=[['discover','discover','发现'],['map','map','校园地图'],['navigate','pin','步行导航'],['routes','walk','出发探索'],['notes','book','探索手记'],['me','user','我的']];
const cover=p=>p.cover||('/shared/'+(p.id==='nmu1'?'nmu-library.jpg':p.theme==='建筑'?'nmu-building.jpg':'nmu-campus.jpg'));
const status=p=>p.trust==='certified'?'<span class="pill green">已经过认证</span>':p.trust==='community'?'<span class="pill orange">由社区共创者上传，请自行分辨</span>':'<span class="pill">地图资料 · 待实地核验</span>';
const title={search:['找个地方，去看看。','搜索校园点位'],navigate:['想去哪里？我们一起走。','校内步行路线规划与网页导航'],discover:['发现校园的另一面','走过很多次的地方，也值得再看一眼。'],map:['把校园装进地图','北方民族大学 · 全校范围 · 点击标记查看点位'],routes:['留一点时间，去探索','选好节奏，跟着镜头走一小段路。'],active:['这一段路，只属于你','不必赶路，先认真看一看身边。'],notes:['把今天留在手记里','拍过的照片，走过的小路，都在这里。'],me:['你好，校园探索者','收藏、创作，还有属于你的探索记录。'],publish:['分享你的校园发现','一个好角度，也可以成为大家的新目的地。']};
function shell(){const page=state.page;$('#sidebar').innerHTML=`<a class="brand" href="#discover"><span class="brand-mark"></span>探索与拍摄</a><div class="brand-sub">EXPLORE & SHOOT</div><nav class="side-nav">${nav.map(([p,i,t])=>`<a class="nav-item ${page===p||p==='discover'&&page==='search'||p==='routes'&&page==='active'?'active':''}" href="#${p}">${icon(i)}${t}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#publish" class="button wide">${icon('plus')} 发布发现</a><div class="sidebar-note"><b>从北方民族大学出发</b>让熟悉的校园<br>多一种打开方式。</div></div>`;
 $('#topbar').innerHTML=`<a href="#discover" class="mobile-brand"><span class="brand-mark"></span>探索与拍摄</a>${page==='search'?'<div class="search-header-label">校园点位搜索</div>':`<form id="search-form" class="search-box">${icon('search')}<input aria-label="搜索校园点位" name="q" maxlength="100" placeholder="搜一个地方，或者一种心情" value="${esc(state.query)}"></form>`}<div class="header-right"><button class="icon-btn mobile-search" id="mobile-search" aria-label="搜索校园点位">${icon('search')}</button><span class="campus-label">${icon('pin')} 北方民族大学</span>${state.account?`<button class="avatar" id="account-open" aria-label="我的账号">${avatarHTML(state.account)}</button>`:'<button class="button secondary small" id="login-open">登录 / 注册</button>'}</div>`;
 $('#search-form')?.addEventListener('submit',e=>{e.preventDefault();openSearch(new FormData(e.target).get('q'));});$('#mobile-search').onclick=()=>openSearch();$('#login-open')?.addEventListener('click',()=>authDialog());$('#account-open')?.addEventListener('click',()=>location.hash='me');
 $('#mobile-nav').innerHTML=nav.filter(x=>x[0]!=='notes').map(([p,i,t])=>`<a href="#${p}" class="${page===p||p==='discover'&&page==='search'||p==='routes'&&page==='active'?'active':''}">${icon(i)}${p==='map'?'地图':p==='routes'?'探索':p==='navigate'?'导航':t}</a>`).join('');let add=$('.mobile-publish');if(!add){add=document.createElement('a');add.href='#publish';add.className='mobile-publish';add.setAttribute('aria-label','发布新点位');add.innerHTML=icon('plus');document.body.append(add);}add.hidden=['search','publish','routes','active','notes','navigate'].includes(page);}
function openSearch(query=state.query){closeModal();state.query=cleanQuery(query);state.theme='全部';state.focusSearch=true;if(state.page==='search')render();else location.hash='search';}
function heading(){if(state.page==='discover')return `<section class="campus-intro"><div class="intro-copy"><span class="eyebrow">北方民族大学 · 校园影像计划</span><h1>熟悉的校园。<br><em>新的视角。</em></h1><p>找一个想去的角落，留一张今天的照片。</p><a href="#navigate" class="button intro-navigate">${icon('walk')} 想去哪里，跟着路线走 ↗</a><a href="#routes" class="intro-link">选一段拍摄探索 <span aria-hidden="true">↗</span></a></div><figure class="intro-photo"><img src="/shared/nmu-campus.jpg" alt="北方民族大学校园参考照片"><figcaption>校园参考照片 · 国家民委 / 北方民族大学</figcaption><a href="#map" class="intro-location glass-surface">${icon('pin')}<span>校园里的下一站<small>${state.catalog.points.length} 个点位等你发现</small></span><span aria-hidden="true">↗</span></a></figure></section>`;const [h,p]=title[state.page]||title.discover;return `<div class="page-heading"><div><h1>${h}</h1><p>${p}</p></div></div>`;}
function filtered(){const order=['nmu1','nmu8','nmu2','nmu6','nmu3','nmu7','nmu4','nmu5'];return state.catalog.points.filter(p=>(state.theme==='全部'||p.theme===state.theme)&&(!state.query||[p.name,p.description,p.theme].join(' ').includes(state.query))).sort((a,b)=>{const x=order.indexOf(a.id),y=order.indexOf(b.id);return (x<0?-1:x)-(y<0?-1:y)||Date.parse(b.createdAt)-Date.parse(a.createdAt);});}
function chips(){return `<div class="chips">${['全部','建筑','自然','人文','运动'].map(t=>`<button class="chip ${state.theme===t?'active':''}" data-theme="${t}">${t==='全部'?'为你推荐':t==='建筑'?'建筑光影':t==='自然'?'自然角落':t==='人文'?'校园日常':'运动瞬间'}</button>`).join('')}</div>`;}
function card(p,i){return `<article class="point-card" style="animation-delay:${Math.min(i,6)*35}ms"><button class="photo-wrap ${!p.open?'closed-photo':''}" data-point="${p.id}" aria-label="查看${esc(p.name)}" style="width:100%;padding:0;display:block"><img src="${esc(cover(p))}" alt="${p.cover?esc(p.name):p.id==='nmu1'?'北方民族大学图书馆参考照片':'北方民族大学校园参考配图'}" loading="${i<3?'eager':'lazy'}"><span class="photo-label">${p.trust==='certified'?'已认证':p.trust==='community'?'社区共创':p.theme+' · 推荐探索'}</span><span class="photo-caption">${p.theme==='建筑'?'在光影里，停留一会':p.theme==='运动'?'把奔跑的日常定格':'日常，也会有新风景'}</span></button><div class="photo-credit">${p.cover?'探索官 '+esc(p.authorName):'校园参考配图 · 国家民委 / 北方民族大学'}</div><button class="card-title" data-point="${p.id}">${esc(p.name)}</button><p class="card-description">${esc(p.description)}</p><div class="card-bottom"><span>${icon('pin')}${p.open?'北方民族大学':'暂时关闭'}</span><button class="text-btn card-route" data-route-to="${p.id}" ${p.open?'':'disabled'} aria-label="步行前往${esc(p.name)}">↗ 去这里</button><button class="icon-btn bookmark ${state.account?.bookmarks?.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${state.account?.bookmarks?.includes(p.id)?'取消收藏':'收藏'}${esc(p.name)}">${icon('heart')}</button></div></article>`;}
function discovery(){const points=filtered();return `${heading()}<div class="feed-layout"><div>${chips()}${state.query?`<p class="muted">「${esc(state.query)}」的发现 <button class="text-btn" id="clear-search">清除搜索</button></p>`:''}<div class="feed-grid">${points.map(card).join('')}</div>${!points.length?'<div class="empty">这个角落，还等着你来发现。<br>试试其他分类，或分享一个新点位。</div>':''}</div><aside class="feed-aside"><div class="daily-card"><span class="daily-doodle">&</span><span class="eyebrow">TODAY’S LITTLE PLAN</span><h2>拿起相机<br>重新认识校园</h2><p>给自己 20 分钟<br>从图书馆的一束光开始。</p><a href="#routes" class="button">${icon('walk')} 选一条小路</a></div><div class="aside-title">校园，近在眼前 <span>on the map</span></div><button class="map-open" id="map-open"><img src="/shared/nmu-campus.jpg" alt="北方民族大学校园参考照片"><div><strong>${state.catalog.points.length} 个起点，一整座校园</strong><small>打开真实地图，找找下一个目的地</small></div></button><a class="aside-link" href="#publish">${icon('camera')} 成为校园探索官，分享新发现</a><a class="aside-link" href="#notes">${icon('book')} 翻一翻自己的探索手记</a><p class="aside-text">慢一点，没关系。<br>照片没有标准答案，<br>发现也不需要走得很远。</p></aside></div>`;}
function goNavigate(id){const p=state.catalog.points.find(p=>p.id===id&&p.open);if(id&&!p){toast('这个点位目前不可前往');return;}closeModal();state.navTarget=id||null;location.hash='navigate';if(state.page==='navigate')render();}
function bindPoints(root=document){root.querySelectorAll('[data-route-to]').forEach(b=>b.onclick=()=>goNavigate(b.dataset.routeTo));root.querySelectorAll('[data-point]').forEach(b=>b.onclick=()=>pointDialog(b.dataset.point));root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>bookmark(b.dataset.save));root.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{state.theme=b.dataset.theme;render();});}
async function bookmark(id){if(!await requireAccount())return;try{const result=await api('/api/bookmarks','POST',{pointId:id});state.account.bookmarks=result.bookmarks;document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{b.classList.toggle('saved',result.bookmarks.includes(id));b.setAttribute('aria-label',result.bookmarks.includes(id)?'取消收藏':'收藏');});toast(result.bookmarks.includes(id)?'已经放进你的收藏':'已取消收藏');}catch(e){toast(e.message);}}
function pointDialog(id){const p=state.catalog.points.find(p=>p.id===id);if(!p)return;modal(p.name,`<img class="detail-cover" src="${esc(cover(p))}" alt="${esc(p.name)}${p.cover?'':'校园参考配图'}">${!p.cover?'<p class="photo-credit">校园参考配图 · 不代表该点位的当前现场</p>':''}${status(p)}<div class="detail-meta"><span class="pill">${esc(p.theme)}</span><span class="pill">${p.open?'可前往探索':'暂时关闭'}</span></div><p class="detail-description">${esc(p.description)}</p><div class="detail-info"><b>拍摄前，留意这些</b>${esc(p.condition)}</div><p class="detail-source">资料来源：${esc(p.source)}<br>坐标：${p.lng.toFixed(6)}, ${p.lat.toFixed(6)} · WGS84${p.verifiedAt?'<br>认证日期：'+esc(p.verifiedAt):''}</p><div class="button-row"><button class="button" id="point-navigate" ${p.open?'':'disabled'}>${icon('walk')} 到这里去</button><button class="button secondary" id="point-map">${icon('map')} 在地图上查看</button><button class="button secondary" data-save="${p.id}">${icon('heart')} 收藏</button>${state.account?.scoutStatus==='approved'?'<button class="text-btn" id="report-open">反馈点位问题</button>':''}</div>`,d=>{bindPoints(d);$('#point-navigate',d).onclick=()=>goNavigate(id);$('#point-map',d).onclick=()=>{closeModal();state.focusPoint=id;state.theme='全部';state.query='';location.hash='map';if(state.page==='map')render();};$('#report-open',d)?.addEventListener('click',()=>reportDialog(p));});}
function reportDialog(p){modal('反馈点位问题',`<p class="muted">${esc(p.name)} · 反馈会同步到管理后台，由管理员确认后处理。</p><form id="report-form"><label>问题类型<select name="category"><option>位置或资料有误</option><option>暂时无法进入</option><option>拍摄条件变化</option><option>其他问题</option></select></label><label>具体情况<textarea name="description" required minlength="5" maxlength="1000" placeholder="描述现场情况，帮助管理员判断…"></textarea></label>${errorHTML}<button class="button wide" type="submit">提交反馈</button></form>`,d=>{const draft=bindDraftForm($('#report-form',d),accountDraft('report:'+p.id),['category','description']);$('#report-form',d).onsubmit=e=>formSubmit(e,async f=>{await api('/api/reports','POST',{...f,pointId:p.id});await draft.clear().catch(()=>{});closeModal();toast('反馈已送达管理员');});return()=>draft.destroy();});}
function mapPage(){return `${heading()}<div class="map-entry"><span>地图和列表，一起找到下一站。</span><a href="#navigate" class="button">${icon('walk')} 路线规划与导航</a></div>${mapExplorerHTML(filtered(),chips(),cover)}<p class="muted" style="margin:14px 0 0">点位依据公开地图资料，现场通行和拍摄条件以学校规定为准。</p>`;}
async function setupMap(){
 const el=$('#campus-map'),points=filtered();
 let map;
 const select=(id,{pan=true,bringIntoView=false}={})=>{
   const p=chooseMapPoint(points,id);if(!p||!el.isConnected)return;
   state.mapSelected=id;
   document.querySelectorAll('[data-focus]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.focus===id)));
   map?.select(id,{pan});
   const info=$('#map-point-info');
   info.innerHTML=mapPointHTML(p,{cover,status,saved:state.account?.bookmarks?.includes(id),canReport:state.account?.scoutStatus==='approved',expanded:!!state.mapExpanded});
   bindPoints(info);
   $('.map-detail-toggle',info).onclick=e=>{
     state.mapExpanded=!state.mapExpanded;
     e.currentTarget.setAttribute('aria-expanded',String(state.mapExpanded));
     e.currentTarget.textContent=state.mapExpanded?'收起介绍 ↑':'展开介绍 ↓';
     $('#map-selected-body').classList.toggle('expanded',state.mapExpanded);
   };
   $('.map-report',info)?.addEventListener('click',()=>reportDialog(p));
   if(bringIntoView&&matchMedia('(max-width:650px)').matches)el.closest('.map-stage').scrollIntoView({block:'start',behavior:'instant'});
 };
 map=await campusMap(el,{...state.catalog,points},{onPoint:id=>select(id)});
 if(!el.isConnected){map.destroy();return;}
 state.map=map;
 const initial=state.focusPoint||state.mapSelected;
 if(initial)select(initial,{pan:!!state.focusPoint});
 if(!chooseMapPoint(points,initial))state.mapSelected=null;
 state.focusPoint=null;
 document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>select(b.dataset.focus,{bringIntoView:true}));
 $('#map-reset').onclick=()=>{map.select(null,{pan:false});map.overview();state.mapSelected=null;state.mapExpanded=false;document.querySelectorAll('[data-focus]').forEach(b=>b.setAttribute('aria-pressed','false'));$('#map-point-info').innerHTML='<div class="map-selection-empty"><div><strong>全校范围，重新出发。</strong><p>点选地图标记或列表，继续浏览校园点位。</p></div></div>';};
 $('#locate').onclick=()=>locate(map);
}
function locate(map){if(!state.catalog.map?.tencentKey){toast('腾讯地图尚未配置，请联系管理员');return;}toast('正在获取位置，请允许浏览器定位');locationFor(state.catalog).getCurrentPosition(p=>{map.locate({lng:p.coords.longitude,lat:p.coords.latitude,accuracy:p.coords.accuracy});toast(p.coords.accuracy>200?'定位精度较低，请到室外再试':'已获取当前位置');},e=>toast(e.code===1?'定位权限未开启，可在浏览器设置中允许':'暂时无法获取位置，请稍后重试'),{enableHighAccuracy:true,timeout:15000,maximumAge:10000});}
function authDialog(tab='login'){closeModal();stopTracking();stopNavigation();try{sessionStorage.setItem('campus-preferences',JSON.stringify(state.preferences));}catch{}location.assign(authURL('user',tab,'/#'+state.page));}
async function requireAccount(){if(state.account)return true;authDialog();return false;}
async function loadPrivate(){if(state.account){state.sessions=await api('/api/sessions');state.active=state.sessions.find(s=>['active','paused'].includes(s.status))||null;}else{state.sessions=[];state.active=null;}}
async function render(){state.taskDraftCleanups?.forEach(fn=>fn());state.taskDraftCleanups=[];state.publishBinding?.destroy();state.publishBinding=null;state.journey?.destroy();state.journey=null;state.map?.destroy();state.map=null;if(state.page!=='active'){stopTracking();stopNavigation();}shell();if(state.page==='search'){if(!$('#campus-search-form'))$('#main').innerHTML=searchHTML(state.query);bindSearch({query:state.query,setQuery:q=>state.query=q,points:state.catalog.points,card,bindCards:bindPoints,focus:state.focusSearch});state.focusSearch=false;return;}if(state.page==='navigate'){$('#main').innerHTML=journeyHTML(state.catalog,state.navTarget);const el=$('#journey-map');try{const journey=await mountJourney(state.catalog);if(el.isConnected)state.journey=journey;else journey.destroy();}catch(e){toast(e.message);const message=$('#journey-message');if(message)message.textContent='地图加载失败，请刷新重试：'+e.message;}return;}let html=state.page==='discover'?discovery():state.page==='map'?mapPage():null;if(html){$('#main').innerHTML=html;bindPoints();$('#map-open')?.addEventListener('click',()=>location.hash='map');$('#clear-search')?.addEventListener('click',()=>{state.query='';render();});if(state.page==='map')setupMap().catch(e=>toast(e.message));return;}await extraPage();}
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);state.page=p==='explore'?'discover':title[p]?p:'discover';render().catch(e=>toast(e.message));window.scrollTo(0,0);});
function preferenceGroup(label,key,values){return `<div><label>${label}</label><div class="chips">${values.map(([value,text])=>`<button class="chip ${state.preferences[key]===value?'active':''}" data-pref="${key}" data-value="${value}">${text}</button>`).join('')}</div></div>`;}
async function routePage(){const p=state.preferences,plans=await api('/api/plan','POST',p);if(state.page!=='routes')return;$('#main').innerHTML=`${heading()}${state.active?`<div class="notice" style="margin-bottom:20px">你有一段尚未结束的探索：${esc(state.active.routeName)} <a href="#active" class="text-btn">继续探索</a></div>`:''}<div class="route-layout"><section class="preference-box"><h3>今天想怎么走？</h3>${preferenceGroup('留出多少时间','budget',[[15,'15 分钟'],[20,'20 分钟'],[30,'30 分钟']])}${preferenceGroup('和谁一起','people',[[1,'一个人'],[2,'两个人']])}${preferenceGroup('步行节奏','intensity',[['轻松','轻松'],['适中','适中']])}<label>想拍什么<select id="route-theme">${['全部','建筑','自然','人文','运动'].map(t=>`<option ${p.theme===t?'selected':''}>${t}</option>`).join('')}</select></label><label>探索方式<select id="route-mode"><option value="fixed" ${p.mode==='fixed'?'selected':''}>跟着拍摄任务走</option><option value="guide" ${p.mode==='guide'?'selected':''}>只看点位导览</option><option value="personal" ${p.mode==='personal'?'selected':''}>按偏好匹配任务</option></select></label><p class="muted">时间含步行、拍摄与 20% 余量。当前路线时间为估算。</p></section><div class="route-list">${plans.map((r,i)=>{const point=state.catalog.points.find(p=>p.id===r.points[0]);return `<article class="route-card"><img class="route-image" src="${esc(cover(point||{}))}" alt="北方民族大学校园参考配图"><div class="route-content"><span class="pill ${r.match?'green':''}">${esc(r.theme)} · ${esc(r.intensity)}步行</span><h2>${esc(r.name)}</h2><p class="route-path">${r.points.map(id=>esc(state.catalog.points.find(p=>p.id===id)?.name||'已下线点位')).join(' / ')}</p><p class="muted">步行 ${r.walk} 分钟 + 拍摄 ${r.stay} 分钟 + 余量 ${r.buffer} 分钟</p><div class="route-bottom"><span class="route-time"><strong>${r.total}</strong>分钟 · ${r.points.length} 个点位</span><button class="button secondary" data-route-preview="${r.id}">查看路线</button><button class="button ${r.available?'':'secondary'}" data-start="${r.id}" ${r.available?'':'disabled'}>${r.available?'就走这条':'暂不可开始'}</button></div>${r.reason?`<p class="muted" style="margin:12px 0 0">${esc(r.reason)}</p>`:''}</div></article>`;}).join('')}<p class="muted">配图为校园参考照片。拍摄任务来自已审核模板；按偏好匹配暂未连接 AI 模型。</p></div></div>`;
 document.querySelectorAll('[data-route-preview]').forEach(b=>b.onclick=()=>routePreview(plans.find(r=>r.id===b.dataset.routePreview)));document.querySelectorAll('[data-pref]').forEach(b=>b.onclick=()=>{state.preferences[b.dataset.pref]=['budget','people'].includes(b.dataset.pref)?Number(b.dataset.value):b.dataset.value;routePage().catch(e=>toast(e.message));});$('#route-theme').onchange=e=>{p.theme=e.target.value;routePage().catch(e=>toast(e.message));};$('#route-mode').onchange=e=>{p.mode=e.target.value;routePage().catch(e=>toast(e.message));};document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{if(!await requireAccount())return;try{b.disabled=true;state.active=await api('/api/sessions','POST',{routeId:b.dataset.start,preferences:p});location.hash='active';toast('小路已经准备好，出发吧');}catch(e){toast(e.message);b.disabled=false;}});
}

function routePreview(route){const stops=route.points.map(id=>state.catalog.points.find(p=>p.id===id)).filter(Boolean);modal(route.name,`<div id="route-preview-map" class="map-canvas" aria-label="步行路线预览"></div><ol class="route-stops">${stops.map((p,i)=>`<li><b>${i+1}</b><span>${esc(p.name)}</span></li>`).join('')}</ol><p id="route-preview-distance" class="muted">正在请求腾讯步行路线…</p><p class="muted">蓝线由腾讯步行服务规划，请以现场入口和通行条件为准。</p>`,d=>{let map;campusMap($('#route-preview-map',d),{...state.catalog,points:stops},{onPoint:pointDialog,routeStops:stops}).then(m=>{if(!d.isConnected){m.destroy();return;}map=m;m.referenceReady?.then(()=>{if(!d.isConnected)return;$('#route-preview-distance',d).textContent=m.reference.missing?(m.reference.reason||'部分腾讯路线暂不可用'):'腾讯规划：点位间步行约 '+Math.round(m.reference.length)+' 米';});}).catch(e=>toast(e.message));return()=>map?.destroy();});}
let watch=null,trackLast=0;
function stopTracking(){if(watch!==null){locationFor(state.catalog).clearWatch(watch);watch=null;}}
function startTracking(){if(!state.active||state.active.status!=='active'){toast('请先恢复探索，再记录轨迹');return;}if(!state.catalog.map?.tencentKey){toast('腾讯地图尚未配置，请联系管理员');return;}if(watch!==null){stopTracking();activePage();toast('轨迹记录已停止');return;}const sessionId=state.active.id;watch=locationFor(state.catalog).watchPosition(async pos=>{if(watch===null||state.page!=='active'||state.active?.id!==sessionId||state.active.status!=='active')return;const p={lng:pos.coords.longitude,lat:pos.coords.latitude,accuracy:pos.coords.accuracy,at:Math.round(pos.timestamp)};state.map?.locate(p);if(p.accuracy>200){$('#track-message')&&( $('#track-message').textContent='定位精度较低，等待更准确的位置…');return;}if(!inCampus(p,state.catalog.campus)){if($('#track-message'))$('#track-message').textContent='当前位置不在校园内，暂不记录轨迹。';return;}if(p.at<=trackLast+3000)return;trackLast=p.at;try{await api('/api/sessions/'+sessionId+'/track','POST',{points:[p]});if(state.active?.id!==sessionId)return;if(!state.active.track.some(x=>x.at===p.at))state.active.track.push(p);state.map?.trail(state.active.track);if($('#track-message'))$('#track-message').textContent=`正在记录 · ${state.active.track.length} 个轨迹点 · 精度约 ${Math.round(p.accuracy)} 米`;}catch(e){toast(e.message);stopTracking();if($('#track-message'))$('#track-message').textContent='轨迹记录已停止。';}},e=>{stopTracking();toast(e.code===1?'定位权限未开启，请在浏览器设置中允许':'定位暂时不可用，已停止记录');activePage();},{enableHighAccuracy:true,maximumAge:3000,timeout:20000});toast('已请求定位，将只记录校园内的实时位置');activePage();}
async function sessionAction(body){try{const id=state.active.id;state.active=await api('/api/sessions/'+id,'PATCH',body);if(['pause','finish','exit'].includes(body.action)){stopTracking();stopNavigation();}if(['finish','exit'].includes(body.action)){await loadPrivate();location.hash='notes';toast(body.action==='finish'?'这一段探索，已收进手记':'探索已结束，记录已保留');}else{await activePage();if(body.action==='task'){toast(body.status==='done'?'又收集到了一个校园瞬间':'已记录跳过原因');const main=$('#main');main.classList.remove('celebrate');void main.offsetWidth;main.classList.add('celebrate');setTimeout(()=>main.classList.remove('celebrate'),450);}}return true;}catch(e){toast(e.message);if(body.action==='photo')throw e;return false;}}
function skipDialog(task){modal('这一次，先跳过',`<form id="skip-form"><p class="muted">${esc(task.pointName)}</p><label>为什么跳过？<textarea name="reason" required maxlength="300" placeholder="例如：入口暂时关闭、现场人太多…"></textarea></label>${errorHTML}<button class="button wide" type="submit">记录并跳过</button></form>`,d=>{const draft=bindDraftForm($('#skip-form',d),accountDraft('skip:'+state.active.id+':'+task.id),['reason']);$('#skip-form',d).onsubmit=e=>formSubmit(e,async f=>{if(await sessionAction({action:'task',taskId:task.id,status:'skipped',reason:f.reason})){await draft.clear().catch(()=>{});closeModal();}else throw Error('跳过原因未提交，请重试；本机草稿仍会保留。');});return()=>draft.destroy();});}
function activePage(){state.taskDraftCleanups?.forEach(fn=>fn());state.taskDraftCleanups=[];const s=state.active;if(!s||!state.account){stopTracking();stopNavigation();$('#main').innerHTML=`${heading()}<div class="empty">还没有正在进行的探索。<br><a href="#routes" class="button" style="margin-top:18px">选一条小路</a></div>`;return;}if(s.status!=='active'||s.blocked?.length){stopTracking();stopNavigation();}const done=s.tasks.filter(t=>t.status!=='pending').length;$('#main').innerHTML=`${heading()}<section class="active-top"><div style="flex:1"><span class="eyebrow">YOUR CAMPUS WALK</span><h2 style="margin-top:12px">${esc(s.routeName)}</h2><span class="muted">${s.status==='paused'?'已暂停':'正在探索'} · ${s.preferences.people} 人 · ${s.plan.total} 分钟预算内计划</span><div class="progress"><span style="width:${done/s.tasks.length*100}%"></span></div><small class="muted">已收集 ${done} / ${s.tasks.length} 个点位 · 完成情况由你自己记录</small></div><div class="button-row"><button class="button secondary" id="pause">${s.status==='paused'?'继续探索':'先歇一会'}</button><button class="text-btn" id="end-early">结束这次探索</button></div></section>${s.blocked?.length?`<p class="notice">${esc(s.blocked.join('、'))} 已下线。请结束本次探索，选择其他开放点位。</p>`:''}<div class="active-layout"><div>${s.tasks.map((t,i)=>`<article class="task-card ${t.status==='done'?'done':''}"><div class="task-top"><span class="task-number">${t.status==='done'?icon('check'):i+1}</span><h3>${esc(t.pointName)}</h3><span class="pill ${t.status==='done'?'green':''}" style="margin-left:auto">${t.status==='done'?'已完成':t.status==='skipped'?'已跳过':'待探索'}</span></div><h4>${esc(t.title)}</h4><ol>${t.steps.map(st=>`<li>${esc(st)}</li>`).join('')}</ol>${t.reason?`<p class="muted">跳过原因：${esc(t.reason)}</p>`:''}${t.mediaId?`<img src="/media/${t.mediaId}" alt="我的探索照片">`:''}<div class="button-row">${t.status==='pending'?`<button class="button" data-done="${t.id}" ${s.status!=='active'||s.blocked?.length?'disabled':''}>${icon('check')} 收集这一刻</button><button class="button secondary" data-skip="${t.id}" ${s.status!=='active'||s.blocked?.length?'disabled':''}>跳过</button>`:''}<button class="button secondary" data-photo="${t.id}">${icon('camera')} ${t.mediaId?'更换照片':'拍一张'}</button><button class="text-btn" data-point="${t.pointId}">查看点位</button></div></article>`).join('')}<button class="button wide dark" id="finish" ${done<s.tasks.length?'disabled':''}>把这段探索收进手记</button></div><aside class="trail-panel">${navigationPanel(s,state.catalog)}<button class="button secondary wide" id="tracking">${icon('pin')} ${watch===null?'开启实时轨迹':'停止记录轨迹'}</button><p id="track-message" class="muted" style="margin-top:13px">${watch!==null?'<span class="tracking-dot"></span>正在定位并记录':s.track.length?'已记录 '+s.track.length+' 个轨迹点':'只有开启后才会记录位置。离开本页面会停止记录。'}</p><p class="muted">轨迹与拍摄照片仅当前账号可见。腾讯处理定位信息；开启记录后轨迹保存到项目服务器，地图显示时腾讯处理轨迹坐标。未开启定位也可以完成拍摄任务。</p></aside></div>`;
 bindPoints();$('#pause').onclick=()=>sessionAction({action:s.status==='paused'?'resume':'pause'});$('#end-early').onclick=()=>modal('结束这次探索？','<p class="muted">已完成的任务和照片会保存在探索手记中。</p><button class="button wide" id="confirm-exit">结束并保留记录</button>',d=>{$('#confirm-exit',d).onclick=()=>{closeModal();sessionAction({action:'exit'});};});$('#finish').onclick=()=>sessionAction({action:'finish'});$('#tracking').onclick=startTracking;document.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>sessionAction({action:'task',taskId:b.dataset.done,status:'done'}));document.querySelectorAll('[data-skip]').forEach(b=>b.onclick=()=>skipDialog(s.tasks.find(t=>t.id===b.dataset.skip)));document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>draftPhoto(async m=>{if(state.active?.id!==s.id)throw Error('探索记录已切换，请重新打开原记录后提交');await sessionAction({action:'photo',taskId:b.dataset.photo,mediaId:m.id});},'photo:'+s.id+':'+b.dataset.photo,{confirmedMediaId:s.tasks.find(t=>t.id===b.dataset.photo)?.mediaId}));decoratePhotoDrafts(s);const el=$('#trail-map');state.map?.destroy();state.map=null;campusMap(el,{...state.catalog,points:state.catalog.points.filter(p=>s.tasks.some(t=>t.pointId===p.id))},{onPoint:pointDialog,trail:s.track,routeStops:s.tasks.map(t=>state.catalog.points.find(p=>p.id===t.pointId)).filter(Boolean)}).then(m=>{if(el.isConnected){state.map=m;bindNavigation(s,state.catalog,m);}else m.destroy();}).catch(e=>toast(e.message));}
function decoratePhotoDrafts(session){
 document.querySelectorAll('[data-photo]').forEach(button=>{
   const task=session.tasks.find(t=>t.id===button.dataset.photo);
   const draft=accountDraft('photo:'+session.id+':'+task.id);
   const hint=document.createElement('small');hint.className='task-draft-hint';hint.hidden=true;
   hint.textContent='有一张照片草稿仅存本机 · 点击拍摄按钮可恢复';button.closest('.button-row').before(hint);
   let restored=false;
   const unsubscribe=draft.subscribe(({phase})=>{if(phase==='saved')restored=true;if(['empty','submitted'].includes(phase))hint.hidden=true;else if(restored&&['saved','restored'].includes(phase))hint.hidden=false;});
   state.taskDraftCleanups.push(unsubscribe);
   draft.read().then(data=>{if(!button.isConnected)return;restored=!!data.photo&&data.uploaded?.id!==task.mediaId;hint.hidden=!restored;}).catch(()=>{});
 });
}
function noteDialog(s){modal(s.routeName,`<p class="muted">${date(s.createdAt)} · ${s.status==='completed'?'已完成':s.status==='ended'?'提前结束':'进行中'}</p>${s.tasks.map(t=>`<div class="detail-info"><b>${esc(t.pointName)} · ${t.status==='done'?'已完成':t.status==='skipped'?'已跳过':'未完成'}</b>${esc(t.title)}${t.reason?'<p class="muted">'+esc(t.reason)+'</p>':''}${t.mediaId?`<img style="margin-top:12px;border-radius:10px" src="/media/${t.mediaId}" alt="我的探索照片">`:''}</div>`).join('')}${s.track.length?'<h3>我走过的轨迹</h3><div id="note-trail" class="map-canvas" style="height:260px;margin-bottom:24px"></div>':''}<form id="feedback-form"><label>这次探索怎么样？<select name="rating">${[[0,'还没评分'],[5,'很喜欢'],[4,'不错'],[3,'一般'],[2,'有待改进'],[1,'不太满意']].map(([v,t])=>`<option value="${v}" ${s.rating===v?'selected':''}>${t}</option>`).join('')}</select></label><label>写一点感受<textarea name="feedback" maxlength="2000" placeholder="哪一处让你停留了更久？">${esc(s.feedback)}</textarea></label>${errorHTML}<div class="button-row"><button class="button" type="submit">保存感受</button><a class="button secondary" href="/api/sessions/${s.id}/export" download>导出手记</a></div></form><p class="muted" style="margin:20px 0 0">已记录 ${s.track.length} 个轨迹点。导出包含照片，不包含精确位置。</p>`,d=>{let map;const el=$('#note-trail',d);if(el)campusMap(el,{...state.catalog,points:[]},{trail:s.track}).then(m=>{if(el.isConnected)map=m;else m.destroy();}).catch(e=>toast(e.message));const draft=bindDraftForm($('#feedback-form',d),accountDraft('note:'+s.id),['rating','feedback'],{emptyLabel:s.feedback||s.rating?'当前感受已提交到账号 · 后续编辑将另存本机草稿':undefined});$('#feedback-form',d).onsubmit=e=>formSubmit(e,async f=>{await api('/api/sessions/'+s.id,'PATCH',{action:'feedback',feedback:f.feedback,rating:Number(f.rating)});await draft.clear().catch(()=>{});await loadPrivate();closeModal();toast('感受已保存');});return()=>{map?.destroy();draft.destroy();};});}
function notesPage(){if(!state.account)return loginGate('把探索留下来','登录后，照片与探索手记会保存到你的账号。');return `${heading()}<div class="stack">${[...state.sessions].reverse().map(s=>`<article class="record"><div><h3>${esc(s.routeName)}</h3><p>${date(s.createdAt)} · ${s.tasks.filter(t=>t.status==='done').length} 个任务已完成 · ${s.tasks.filter(t=>t.mediaId).length} 张照片</p></div><div class="button-row"><span class="pill ${s.status==='completed'?'green':''}">${s.status==='completed'?'已完成':s.status==='ended'?'提前结束':s.status==='paused'?'已暂停':'探索中'}</span><button class="button secondary small" data-note="${s.id}">翻开手记</button>${['active','paused'].includes(s.status)?'<a href="#active" class="button small">继续</a>':''}<button class="text-btn" data-delete-note="${s.id}">删除</button></div></article>`).join('')||'<div class="empty">第一篇手记，从今天的一个小发现开始。<br><a href="#routes" class="button secondary" style="margin-top:16px">开始探索</a></div>'}</div>`;}
function loginGate(h,p){return `${heading()}<div class="empty"><h2>${h}</h2><p>${p}</p><button class="button" id="gate-login">登录 / 邀请码注册</button></div>`;}
async function mePage(){const a=state.account;if(!a){$('#main').innerHTML=loginGate('加入你的校园探索圈','用管理员提供的邀请码注册，收藏点位、记录旅途和参与共创。');$('#gate-login').onclick=()=>authDialog();return;}const community=await api('/api/my/community');if(state.page!=='me')return;const statusText={none:'等待你的第一份发现',pending:'申请已送达 · 等待管理员确认',approved:'你已经是校园探索官',rejected:'申请暂未通过 · 可以补充理由重新申请'}[a.scoutStatus];$('#main').innerHTML=`${heading()}<div class="account-panel"><section class="profile"><div class="profile-avatar">${avatarHTML(a)}</div><div><h2>${esc(a.nickname)}</h2><p>@${esc(a.username)} · ${a.scoutStatus==='approved'?'校园探索官':'校园探索者'}</p></div><div class="profile-actions"><button class="button secondary small" id="edit-profile">编辑个人资料</button><button class="button secondary small" id="change-password">修改密码</button><button class="text-btn" id="user-logout">退出登录</button></div></section><div class="account-grid"><section class="account-tile"><h3>${icon('camera')} 校园探索官</h3><p>${statusText}</p><p>分享新点位，帮助大家发现校园；提交现场问题，一起维护可信的信息。</p>${a.scoutStatus==='approved'?'<a class="button small" href="#publish">发布一个新发现</a>':a.scoutStatus==='pending'?'<span class="pill">审核中</span>':'<button class="button small" id="apply-scout">申请成为探索官</button>'}${community.applications.at(-1)?.note?`<p class="muted">管理员回复：${esc(community.applications.at(-1).note)}</p>`:''}</section><section class="account-tile"><h3>${icon('book')} 我的探索手记</h3><p>已留下 ${state.sessions.length} 段探索记录<br>照片和实时轨迹仅自己可见。</p><a class="button secondary small" href="#notes">翻开手记</a></section></div><h3 style="margin-bottom:20px">我的收藏 <span class="muted">${a.bookmarks?.length||0}</span></h3><div class="feed-grid">${state.catalog.points.filter(p=>a.bookmarks?.includes(p.id)).map(card).join('')}</div>${!a.bookmarks?.length?'<p class="muted">在喜欢的点位旁点一下爱心，就能在这里找到。</p>':''}<h3 style="margin:32px 0 18px">我的社区发现</h3><div class="stack">${community.points.map(p=>`<div class="record"><div><h3>${esc(p.name)}</h3><p>${p.published?'已发布':'已下线'} · ${date(p.createdAt)}</p></div>${status(p)}</div>`).join('')||'<p class="muted">还没有发布点位。校园的下一个好角度，等你来分享。</p>'}</div>${community.reports.length?'<h3 style="margin-top:28px">我的问题反馈</h3>'+community.reports.map(r=>`<div class="detail-info"><b>${esc(state.catalog.points.find(p=>p.id===r.pointId)?.name||'点位反馈')}</b>${esc(r.description)}<p class="muted">${r.status==='pending'?'管理员处理中':r.status==='resolved'?'已处理':'未采纳'}${r.note?' · '+esc(r.note):''}</p></div>`).join(''):''}</div>`;
 bindPoints();$('#edit-profile').onclick=()=>profileDialog(state.account,async a=>{state.account=a;state.catalog=await api('/api/catalog');await render();});$('#change-password').onclick=passwordDialog;$('#user-logout').onclick=async()=>{stopTracking();stopNavigation();await api('/api/auth/logout','POST',{});state.account=null;await loadPrivate();render();toast('已退出登录');};$('#apply-scout')?.addEventListener('click',applyScout);
}
function applyScout(){modal('申请成为校园探索官',`<p class="muted">一起找到更多校园角落。申请通过后，可发布新点位和提交现场问题反馈。</p><form id="scout-form"><label>想分享什么样的校园发现？<textarea name="reason" required minlength="5" maxlength="1000" placeholder="简单介绍你的兴趣和想贡献的内容…"></textarea></label>${errorHTML}<button class="button wide" type="submit">提交申请</button></form>`,d=>{const draft=bindDraftForm($('#scout-form',d),accountDraft('scout'),['reason']);$('#scout-form',d).onsubmit=e=>formSubmit(e,async f=>{await api('/api/scout/apply','POST',f);await draft.clear().catch(()=>{});state.account.scoutStatus='pending';closeModal();toast('申请已提交，请等待管理员审核');render();});return()=>draft.destroy();});}
async function publishPage(){if(!state.account){$('#main').innerHTML=loginGate('分享发现，先认识一下','用邀请码注册账号，再申请成为校园探索官。');$('#gate-login').onclick=()=>authDialog('register');return;}if(state.account.scoutStatus!=='approved'){$('#main').innerHTML=`${heading()}<div class="empty"><h2>成为校园探索官，再分享新发现</h2><p>${state.account.scoutStatus==='pending'?'你的申请正在审核中。':'发布权限会在管理员通过申请后开启。'}</p>${state.account.scoutStatus==='pending'?'<a href="#me" class="button secondary">查看申请状态</a>':'<button class="button" id="publish-apply">申请成为校园探索官</button>'}</div>`;$('#publish-apply')?.addEventListener('click',applyScout);return;}let photoId=null,coord=null;$('#main').innerHTML=`${heading()}<div class="publish-layout"><form class="publish-form" id="publish-form"><button class="photo-upload" type="button" id="publish-photo" style="width:100%">${icon('camera')}<span>拍一张，或选择点位照片</span><small>展示现场真实画面，避免无关配图</small></button>${field('给这个地方起个名字','name','text','','required maxlength="60" placeholder="例如：图书馆东侧的光影长廊"')}<label>发现了什么？<textarea name="description" required minlength="5" maxlength="1200" placeholder="介绍这个地方、推荐角度和适合前往的时间…"></textarea></label><label>点位主题<select name="theme"><option>建筑</option><option>自然</option><option>人文</option><option>运动</option></select></label><label>通行与拍摄条件<textarea name="condition" required maxlength="500" placeholder="说明开放情况、注意事项，以及适合拍摄的公共区域…"></textarea></label><label>在地图上点选准确位置</label><div id="publish-map" class="map-canvas publish-map"></div><p id="picked-coordinate" class="muted">点击校园内的位置，放下你的点位标记。</p><div class="notice">发布后即刻可见，并标注「由社区共创者上传，请自行分辨」。管理员审核通过后显示「已经过认证」。</div>${errorHTML}<button class="button wide" type="submit">发布我的发现</button></form><aside class="publish-aside"><h2>Look closer.</h2><h3>你发现的，也许是别人错过的。</h3><p>一段走廊，一个转角，<br>或者熟悉建筑里的新光线。</p><ul><li>使用自己拍摄的现场照片</li><li>位置标记尽量准确</li><li>尊重学校通行与拍摄规定</li><li>不公开他人的私人信息</li></ul></aside></div>`;
 const form=$('#publish-form'),draft=accountDraft('publish'),photoDraft=accountDraft('publish-photo');
 let map,ready=false,submissionId;
 const photoButton=$('#publish-photo'),coordinateLabel=$('#picked-coordinate');
 const showCoord=p=>{coord=p;coordinateLabel.textContent=p?`已选择：${p.lng.toFixed(6)}, ${p.lat.toFixed(6)} · WGS84`:'点击校园内的位置，放下你的点位标记。';map?.pick(p);};
 const binding=bindDraftForm(form,draft,['name','description','theme','condition'],{
   noun:'点位文字与位置',
   onRestore:data=>{if(data.coordinate&&inCampus(data.coordinate,state.catalog.campus))showCoord(data.coordinate);submissionId=data.submissionId;},
   onDiscard:async()=>{showCoord(null);submissionId=null;await photoDraft.clear();photoId=null;photoButton.innerHTML=icon('camera')+'<span>拍一张，或选择点位照片</span><small>展示现场真实画面，避免无关配图</small>';}
 });
 state.publishBinding=binding;
 await binding.ready;
 if(!form.isConnected)return;
 ready=true;
 try{
   const photo=await photoDraft.read();
   if(!form.isConnected)return;
   if(photo.photo){photoId=photo.uploaded?.id||null;photoButton.innerHTML=`<img src="${esc(photo.photo)}" alt="恢复的点位照片"><small>${photoId?'照片已上传，点位尚未发布':'照片仅存本机 · 点击恢复并上传'} · 点击可更换</small>`;}
 }catch{toast('照片草稿读取失败，请勿关闭尚未提交的页面');}
 photoButton.onclick=()=>draftPhoto(async m=>{if(!form.isConnected)throw Error('请回到发布页面后重试');photoId=m.id;photoButton.innerHTML=`<img src="${esc(m.url)}" alt="待发布的点位照片"><small>照片已上传，点位尚未发布 · 点击更换</small>`;},'publish-photo',{keepDraft:true});
 form.onsubmit=e=>formSubmit(e,async f=>{
   if(!photoId)throw Error('请先添加照片，或点击恢复的照片完成上传');
   if(!coord)throw Error('请在地图上选择点位位置');
   submissionId||=crypto.randomUUID();
   await draft.update({fields:f,coordinate:coord,submissionId}).catch(()=>{});
   const point=await api('/api/points','POST',{...f,...coord,mediaId:photoId,submissionId});
   await Promise.all([binding.clear(),photoDraft.clear({submitted:true})]).catch(()=>toast('点位已发布，但本机草稿未能清理，请稍后丢弃。'));
   try{state.catalog=await api('/api/catalog');}catch{state.catalog.points=state.catalog.points.filter(p=>p.id!==point.id).concat(point);toast('点位已发布，列表同步暂时中断，联网后会刷新');}
   state.theme='全部';state.query='';location.hash='discover';toast('新发现已发布，等待管理员认证');pointDialog(point.id);
 });
 const el=$('#publish-map');
 try{
   map=await campusMap(el,state.catalog,{canPick:()=>ready&&!form.querySelector('[type=submit]').disabled,onPick:p=>{
     if(!inCampus(p,state.catalog.campus)){toast('请在北方民族大学校内选择位置');return false;}
     showCoord(p);draft.reopen();draft.update({coordinate:p}).catch(()=>{});
   }});
   if(el.isConnected){state.map=map;if(coord)map.pick(coord);}else map.destroy();
 }catch(e){if(el.isConnected)coordinateLabel.textContent='地图暂时不可用，文字草稿仍可保存。请刷新后继续：'+e.message;}

}
async function extraPage(){if(state.page==='routes')return routePage();if(state.page==='active')return activePage();if(state.page==='me')return mePage();if(state.page==='publish')return publishPage();if(state.page==='notes'){$('#main').innerHTML=notesPage();$('#gate-login')?.addEventListener('click',()=>authDialog());document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>noteDialog(state.sessions.find(s=>s.id===b.dataset.note)));document.querySelectorAll('[data-delete-note]').forEach(b=>b.onclick=()=>modal('删除这篇手记？','<p class="muted">该手记及其中的私人照片将从本地删除，无法恢复。已发布的社区点位照片会保留。</p><button class="button danger wide" id="confirm-delete">确认删除</button>',d=>{$('#confirm-delete',d).onclick=async()=>{try{await api('/api/sessions/'+b.dataset.deleteNote,'DELETE');await loadPrivate();closeModal();render();toast('手记已删除');}catch(e){toast(e.message);}};}));}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopTracking();stopNavigation();}else if(state.page==='active')activePage();});
window.addEventListener('pagehide',()=>{stopTracking();stopNavigation();state.journey?.destroy();});
setInterval(async()=>{try{if(document.hidden||!state.catalog)return;const latest=await api('/api/catalog');const changed=latest.version!==state.catalog.version;state.catalog=latest;if(state.page==='navigate'){state.journey?.refresh(latest);return;}if(state.account){const me=await api('/api/auth/me');if(!me.account){closeModal();state.account=null;stopTracking();stopNavigation();await loadPrivate();render();return;}const scoutChange=me.account.scoutStatus!==state.account.scoutStatus||me.account.nickname!==state.account.nickname||me.account.avatarVersion!==state.account.avatarVersion;state.account=me.account;if(state.page==='active')await loadPrivate();if(changed||scoutChange){if(!$('#publish-form')&&!$('#dialog'))render();}else if(state.page==='active'&&state.active?.blocked?.length&&!$('#dialog')){stopTracking();stopNavigation();render();}}else if(changed&&!$('#dialog'))render();}catch{}},12000);
async function boot(){pruneDrafts();try{try{const p=JSON.parse(sessionStorage.getItem('campus-preferences'));if(p&&[15,20,30].includes(p.budget)&&[1,2].includes(p.people)&&['轻松','适中'].includes(p.intensity)&&['全部','建筑','自然','人文','运动'].includes(p.theme)&&['fixed','guide','personal'].includes(p.mode))state.preferences=p;}catch{}const [catalog,me]=await Promise.all([api('/api/catalog'),api('/api/auth/me')]);state.catalog=catalog;state.account=me.account;await loadPrivate();const p=location.hash.slice(1);state.page=p==='explore'?'discover':title[p]?p:'discover';await render();}catch(e){$('#main').innerHTML=`<div class="empty">${esc(e.message)}<br><button class="button secondary" onclick="location.reload()">重新打开</button></div>`;}}
boot();
